// ========================================
// 修复方案1：使用 execFile 进行参数化执行（推荐）
// ========================================
import { execFile } from "child_process";

export function processUploadedFileFixed(filename: string): void {
    // ✅ 使用 execFile 传递参数数组，避免 shell 解释
    execFile("process.sh", [filename], (error, stdout, stderr) => {
        if (error) {
            console.error(`执行出错: ${error.message}`);
            return;
        }
        console.log(`输出: ${stdout}`);
    });
}

// ========================================
// 修复方案2：严格的输入验证和过滤
// ========================================
import { exec } from "child_process";

export function processUploadedFileValidated(filename: string): void {
    // ✅ 步骤1: 输入验证 - 只允许特定字符集
    const sanitizedFilename = filename.replace(/[^a-zA-Z0-9._-]/g, "");

    // ✅ 步骤2: 长度限制
    if (sanitizedFilename.length > 255) {
        throw new Error("文件名过长");
    }

    // ✅ 步骤3: 防止路径遍历攻击
    if (sanitizedFilename.includes("..")) {
        throw new Error("不允许的文件名");
    }

    // ✅ 步骤4: 使用验证后的文件名
    exec(`/bin/sh process.sh ${sanitizedFilename}`, (error, stdout, stderr) => {
        if (error) {
            console.error(`执行出错: ${error.message}`);
            return;
        }
        console.log(`stdout: ${stdout}`);
    });
}

// ========================================
// 修复方案3：使用白名单验证（最安全）
// ========================================
import { execFile } from "child_process";

// 允许执行的处理脚本白名单
const ALLOWED_SCRIPTS = ["process.sh", "validate.sh", "convert.sh"];

// 允许的文件名模式白名单
const FILENAME_PATTERN = /^[a-zA-Z0-9._-]{1,255}$/;

export function processUploadedFileWhitelist(filename: string): void {
    // ✅ 验证文件名格式
    if (!FILENAME_PATTERN.test(filename)) {
        throw new Error("文件名格式不合法");
    }

    // ✅ 验证脚本是否在白名单中
    const scriptName = "process.sh";
    if (!ALLOWED_SCRIPTS.includes(scriptName)) {
        throw new Error("不允许的脚本");
    }

    // ✅ 使用参数化执行
    execFile(scriptName, [filename], (error, stdout, stderr) => {
        if (error) {
            console.error(`执行出错: ${error.message}`);
            return;
        }
        console.log(`stdout: ${stdout}`);
    });
}

// ========================================
// 修复方案4：使用 spawn 进行流式处理（处理大文件）
// ========================================
import { spawn } from "child_process";

export function processUploadedFileStream(filename: string): void {
    // ✅ 输入验证
    const sanitizedFilename = filename.replace(/[^a-zA-Z0-9._-]/g, "");

    if (!FILENAME_PATTERN.test(sanitizedFilename)) {
        throw new Error("文件名格式不合法");
    }

    // ✅ 使用 spawn 而不是 exec，避免启动 shell
    const childProcess = spawn("process.sh", [sanitizedFilename], {
        // ❌ 不设置 shell: true，避免命令注入
        // shell: false，
    });

    // 处理输出流
    childProcess.stdout.on("data", (data) => {
        console.log(`stdout: ${data}`);
    });

    childProcess.stderr.on("data", (data) => {
        console.error(`stderr: ${data}`);
    });

    childProcess.on("close", (code) => {
        console.log(`子进程退出，退出码: ${code}`);
    });
}

/*
** 最佳实践总结：
** 
** 1. 首选方案：使用 execFile 或 spawn 的数组参数形式，完全避免启动 shell
** 2. 辅助措施：实施严格的输入验证和过滤
** 3. 防御深度：使用白名单机制，仅允许预定义的值
** 4. 文件处理：避免在文件名中使用 Shell 元字符，必要时进行转义
** 5. 错误处理：妥善处理执行错误，避免泄露系统信息
*/
